-- Basile, 30/09/2026 (soir) : l'objectif n° 1 est la MONÉTISATION seule, 2 000 € par mois sur CHACUNE de TikTok,
-- YouTube et Instagram (6 000 € au total), sans les ventes de produits. Et trois changements approuvés : un moteur à
-- la fois, une niche unique (marque média et produits), la preuve avant le prix (cap, feuille de route).
UPDATE buts SET enonce = '2 000 € par mois de monétisation sur chacune des trois plateformes TikTok, YouTube et Instagram (6 000 € au total, sans les ventes de produits)',
  mesure = 'revenus du mois des plateformes tiktok, youtube, instagram (table revenus)', cible = '2000 €/mois par plateforme'
WHERE enonce LIKE '2 000 € par mois de monétisation des contenus%';
